import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    stones = [(int(input[3*i+1]), int(input[3*i+2]), int(input[3*i+3])) for i in range(n)]

    max_radius = 0
    best_choice = []

    # Check single stones
    for i, (a, b, c) in enumerate(stones):
        r = min(a, b, c) / 2
        if r > max_radius:
            max_radius = r
            best_choice = [i + 1]

    # Check pairs of stones
    faces = defaultdict(list)
    for i, (a, b, c) in enumerate(stones, start=1):
        faces[(a, b)].append(i)
        faces[(b, c)].append(i)
        faces[(c, a)].append(i)

    for (x, y), indices in faces.items():
        for i in range(len(indices)):
            for j in range(i + 1, len(indices)):
                a1, b1, c1 = stones[indices[i] - 1]
                a2, b2, c2 = stones[indices[j] - 1]
                if x == a1 and y == b1:
                    r = min(x, y, c1 + c2) / 2
                elif x == a1 and y == c1:
                    r = min(x, y, b1 + b2) / 2
                elif x == b1 and y == c1:
                    r = min(x, y, a1 + a2) / 2
                else:
                    continue
                if r > max_radius:
                    max_radius = r
                    best_choice = [indices[i], indices[j]]

    print(len(best_choice))
    print(" ".join(map(str, best_choice)))

main()
